def transform(grid):
    h, w = len(grid), len(grid[0])
    fives = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]

    def nearby(r, c):
        return sum(
            0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0
            for rr in range(r - 2, r + 3)
            for cc in range(c - 2, c + 3)
            if (rr, cc) != (r, c)
        )

    source = max(fives, key=lambda p: nearby(*p))
    target = next(p for p in fives if p != source)
    dr, dc = target[0] - source[0], target[1] - source[1]

    # Find the connected non-background shape containing the source marker.
    component = {source}
    stack = [source]
    while stack:
        r, c = stack.pop()
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                if grid[rr][cc] != 0 and (rr, cc) not in component:
                    component.add((rr, cc))
                    stack.append((rr, cc))

    out = [row[:] for row in grid]
    out[target[0]][target[1]] = 0
    for r, c in component:
        if (r, c) == source:
            continue
        rr, cc = r + dr, c + dc
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = grid[r][c]
    return out
